			q = { "How do I talk in Sylvanistas chat?", "Who can read [Dreadguard]?", "Is Sylvanistas chat private?" },
			text = "Talk with /sy, /syc and /syld. /syl chat on turns chats on. Not private: never share passwords there.",
			long = "/sy for [Sylvanistas] (everyone), /syc for [Dreadguard] (Dreadguards and up), /syld for [Veterans]. The chats stay off until you say yes (/syl chat on). They aren't private: anyone on the channel can read all three, so never share passwords." },
		{ id = "feat-chat-off", topic = "features",
			q = { "How do I turn off the /sy spam?", "Can I hide Sylvanistas chat?" },
			text = "Type /syl chat off to turn chats off. /syl mute sylvanistas hides one channel. /syl filter add <word> hides lines with a word.",
			long = "/syl chat off turns the chats off on your client: nothing shows or sends. Or /syl mute sylvanistas to hide just that channel, or /syl filter add <word> to hide lines with a word." },
		{ id = "feat-block-terms", topic = "features",
			q = { "How do I hide certain words?", "What does /syl filter do?" },
			text = "Type /syl filter add <word> to hide lines with it, on your screen only. /syl filter shared off ignores the moderators' list.",
			long = "/syl filter add <word> hides addon lines with that word on your screen only: chats, edicts, decrees and Voice. The sender isn't blocked. Moderators also keep a shared list; /syl filter shared off ignores it." },
		{ id = "feat-decrees", topic = "features",
			q = { "What's a Call to arms?", "How do I send a muster?" },
			text = "Dreadguards+: Call to arms (/syl arms) or Muster (/syl muster). Add test for a preview only you see.",
			long = "Dreadguards and up send a Call to arms (an alarm and map marker for every guild) or a Muster (a rally point for 30 minutes). Banshee decrees and Tabard inspections are for the Banshee Court. Others get a local preview; /syl arms test tries it." },
		{ id = "feat-alert-sounds", topic = "features",
			q = { "How do I turn off the alert sounds?", "Why didn't I get the raid warning in my dungeon?" },
			text = "Type /syl sound off for all, or /syl sound <kind> off. In instances alerts wait; /syl alerts always shows them at once.",
			long = "/syl sound off silences them all, or /syl sound vox off (or another kind) for one. In an instance or while Busy, alerts wait until you're out; /syl alerts always shows them at once." },
		{ id = "feat-writs", topic = "features",
			q = { "What's a Banshee Edict?", "How do I answer an edict?" },
			text = "A letter from the Dark Lady in the Decrees tab. Veterans and Dreadguards can answer As you command.",
			long = "A letter from the Dark Lady in the Decrees tab, to the Veterans, to Veterans and Dreadguards, or to all the Forsaken. Veterans and Dreadguards can answer As you command, and the Dark Lady sees how many did." },
		{ id = "feat-net-off", topic = "features",
			q = { "Someone's lines disappeared", "What's net-off?", "Can moderators hide spammers?" },
			text = "Moderators can hide a character or guild from the network. The Decrees tab says who, why, by whom and when.",
			long = "Moderators (the Dark Lady, her Ambassador, her Dark Rangers and the Dreadguard) can hide a character or take a guild off the network for everyone. The Decrees tab lists who's hidden, why, by whom and when." },
		{ id = "feat-acts-log", topic = "features",
			q = { "Who opened the gates?", "What's /syl log?" },
			text = "Type /syl log: decrees, gates and mercies your client saw, with who did them. Kept on your PC only.",
			long = "What this client saw: decrees, gates, mercies and the Dark Lady's switches, each with who did it. It's on the Decrees tab or /syl log, kept on your computer only and never sent." },
		{ id = "feat-patrol", topic = "features",
			q = { "How does the tabard patrol work?", "What's /syl mark?" },
			text = "Type /syl patrol, then walk around: it checks nearby members (15+) for the tabard. /syl mark flags your target.",
			long = "Start a patrol on the Tabards tab (or /syl patrol) and walk through the crowd: it checks nearby members level 15 and up for the Sylvanistas tabard. /syl mark flags your target with a note. Hover anyone to see their last check." },
		{ id = "feat-gear-seen", topic = "features",
			q = { "How do officers save someone's gear?", "What's Gear seen?" },
			text = "Officers: target someone, /syl gear. It keeps what they wear under Gear seen. Nothing is scored or sent.",
			long = "Officers: target someone in range and click Inspect gear on the Tabards tab (or /syl gear). What they wear is kept under Gear seen, to check later. Nothing is scored or sent." },
		{ id = "feat-patrolshare", topic = "features",
			q = { "Can officers share patrol findings?", "What's /syl patrolshare?" },
			text = "Officers: /syl patrolshare on shares your patrol findings with your guild's officers. Off stops it.",
			long = "If you say yes. /syl patrolshare on sends what your patrols find to your guild's officers over guild chat only, and shows you theirs for a day. /syl patrolshare off stops it." },
		{ id = "feat-untabarded", topic = "features",
			q = { "What's the untabarded list?", "What's a Banshee Mercy?" },
			text = "The Dark Lady's list of players caught without the tabard. Only she sees it unless she shows it. Mercy clears a name for a week.",
			long = "Players the Dark Lady's Banshee Inspection caught without the colors; only the Dark Lady sees it unless she chooses to show it. A Banshee Mercy takes a name off for a week. Players under 15 are never listed." },
		{ id = "feat-throne", topic = "features",
			q = { "What can the Dark Lady do in the addon?", "What's the Sanctum tab?" },
			text = "The Dark Lady's tab: Agenda, Court, key rotation. Summon the Veterans and gates are on the Realm tab, the inspection on Tabards. Her Ambassador and Dark Rangers get some tools.",
			long = "The Dark Lady's own tab: her Agenda and week, Hold Audience and key rotation. Her other tools sit where they belong: Summon the Veterans and the gates on the Realm tab, the Banshee Inspection on Tabards, edicts in Decrees. Her Ambassador and Dark Rangers can use some of them." },
		{ id = "feat-agenda", topic = "features",
			q = { "I got a popup about a Banshee event", "What's the Dark Lady's Agenda?" },
			text = "The Dark Lady's Agenda: a popup with the next Banshee event, shown on the Census, with reminders 10 and 1 min before.",
			long = "The Dark Lady sets the next Banshee event: everyone gets a popup with what, when and where, sees it on the Census, and gets reminders 10 minutes and 1 minute before." },
		{ id = "feat-summon-lords", topic = "features",
			q = { "I got 'The Dark Lady summons her Veterans'", "What's Summon the Veterans?" },
			text = "A roll call for Veterans and Dreadguards: answer Present or Busy. The Dark Lady sees who answered.",
			long = "A roll call for Veterans and Dreadguards online: answer Present or Busy. The Dark Lady sees who answered and who didn't, and the Realm tab marks each of them for a while." },
		{ id = "feat-hold-court", topic = "features",
			q = { "What's Hold Audience?", "How do I ask the Dark Lady for an audience?" },
			text = "When the Dark Lady holds an audience, players in her zone get a line: one click asks for an audience.",
			long = "When the Dark Lady opens an audience, everyone in her zone gets a line on the Census and Realm tabs. One click asks for an audience, and she calls players from her queue." },
		{ id = "feat-royal-inspection", topic = "features",
			q = { "What's the Banshee Inspection?", "Why am I patrolling for the Dark Lady?" },
			text = "A tabard check for the Dark Lady: players who said yes patrol for 2 min and report. /syl inspection off opts out.",
			long = "The Dark Lady calls a tabard check: a raid warning, then a sample of players who said yes patrol the tabards around them for 2 minutes and report to her. At most once every 30 minutes. /syl inspection off opts you out." },
		{ id = "feat-steward-hands", topic = "features",
			q = { "What's the Dark Lady's Ambassador?", "Who are the Dark Rangers of the Dark Lady?" },
			text = "The Ambassador acts for the Dark Lady. Dark Rangers are players named to run her Agenda, Voice, roll call and gates.",
			long = "The Ambassador acts for the Dark Lady: they name Dark Rangers, manage the treasury's keepers and use most of the Dark Lady's tools (not audiences, edicts, mercies or her crown). Dark Rangers are players the Dark Lady or Ambassador names to run the roll call, Agenda, Voice, inspection and gates in her name." },
		{ id = "feat-vox", topic = "features",
			q = { "What's Voice of the Forsaken?", "How do I vote?" },
			text = "The Dark Lady's polls: tick your answer before the timer ends. /syl vox off keeps them in chat.",
			long = "The Dark Lady's polls: 2 to 6 answers, open for a short time. A window pops up with check boxes and a countdown; your vote goes to the Dark Lady, and everyone sees the result. /syl vox off keeps questions in chat." },
		{ id = "feat-treasury", topic = "features",
			q = { "What's the Treasury tab?", "How is the treasury balance counted?" },
			text = "The treasury from its keepers' books: gifts by trade or mail count. Everyone sees what the Dark Lady chooses to show.",
			long = "The Forsaken's treasury, from its keepers' books: gold and items given to a keeper by trade or mail are donations. Keepers, the Dark Lady and her Ambassador see it all; everyone else sees what the Dark Lady chooses to show." },
		{ id = "feat-guild-bank", topic = "features",
			q = { "Can I see the Sylvanistas guild bank?", "What's in <Sylvanistas>'s bank?" },
			text = "When the Dark Lady shows it, the Treasury tab has a snapshot of <Sylvanistas>'s bank, with search.",
			long = "When the Dark Lady shows the treasury's book, the Treasury tab has a snapshot of <Sylvanistas>'s guild bank, with search and what's gone since the last snapshot. It's a picture: nothing gets moved." },
		{ id = "feat-treasury-requests", topic = "features",
			q = { "How do I ask the treasury for items?", "What's /syl need?" },
			text = "Veterans and Dreadguards: /syl need 10 then shift-click the item. Keepers see it and you're told when it's done.",
			long = "Veterans and Dreadguards: /syl need 10 and shift-click the item. The keepers see it on their Treasury tab and mark it done or declined, and you're told. The handover is still a normal trade or mail." },
		{ id = "feat-sister-banks", topic = "features",
			q = { "Can the Dark Lady see our guild bank?", "What's /syl bank share?" },
			text = "Only with a yes: /syl bank share on shows your bank snapshot to the Dark Lady's side by whisper. Off takes it back.",
			long = "Only if your guild master or an officer says yes. /syl bank share on shows your bank's snapshot to the Dark Lady, her Ambassador and her Dark Rangers, by whisper, never on the channel. /syl bank share off takes it back." },
		{ id = "feat-donations", topic = "features",
			q = { "How do I know where to donate?", "What's 'taking donations'?" },
			text = "When a keeper takes donations, a line on the Realm and Treasury tabs says who and where.",
			long = "When a keeper types /syl donations on, everyone sees a line on the Realm and Treasury tabs saying he's taking donations, with his zone if he shares it. It goes off when he logs out." },
		{ id = "feat-dues", topic = "features",
			q = { "What are the dues?", "How do I pay the dues?" },
			text = "Open mail or a trade with the Treasurer, then click Send this week's dues on the Treasury tab. Nothing is locked behind paying.",
			long = "One fixed weekly amount for everyone, set by the Dark Lady, sent to the Treasurer. Open your mailbox (Send Mail) or a trade with them, then click Send this week's dues on the Treasury tab: it fills everything in for you to confirm. Nothing is locked behind paying." },
		{ id = "feat-backup", topic = "features",
			q = { "My settings reset, can I save them?", "What's /syl backup?" },
			text = "Type /syl backup to copy your settings as text. Keep it; /syl restore brings it back after a wipe.",
			long = "/syl backup copies your settings (and a keeper's treasury book) as text: keep it in a file. When the beta wipes addon data, /syl restore pastes it back. Nothing is uploaded, and it never holds the channel key." },
		{ id = "feat-world-map", topic = "features",
			q = { "How do I see the Forsaken on the map?", "How do I turn off the map circles?" },
			text = "The map shows soldiers per zone. The round Sylvanistas button (bottom left of the map) or /syl map turns it on or off.",
			long = "The world map shows soldiers per zone and continent, decree icons, the Dark Lady's crown and camps. The round Sylvanistas button at the bottom left of the map turns them on or off; /syl map too. In gamepad mode only continent totals show." },
		{ id = "feat-guildmate-dots", topic = "features",
			q = { "How do I see guildmates on the map?", "How do I share my position with my guild?" },
			text = "Type /syl share to share your spot with your guild; /syl mates shows guildmates on your map.",
			long = "Off by default. /syl share shares your position with your guild, and /syl mates shows guildmates' dots on your map and minimap. It stays inside your guild." },
		{ id = "feat-borders-nameplates", topic = "features",
			q = { "What are the gold wings on portraits?", "What's the star on nameplates?", "How do I turn them off?" },
			text = "Portrait borders and nameplate marks show Sylvanistas ranks. /syl borders off or /syl nameplates off hides them.",
			long = "Elite borders show Sylvanistas rank on your target and focus portraits: gold wings for the Dark Lady, silver for the Dreadguard, gold for Veterans, silver for Dreadguards. Nameplates get small marks (a star for members). /syl borders off or /syl nameplates off hides them." },
		{ id = "feat-alt-links", topic = "features",
			q = { "How do I link my alts?", "Why does my alt count twice?" },
			text = "Type /syl alt add Name on your main, then say yes on the alt. On the beta the offer can't reach the alt yet.",
			long = "/syl alt add Name on your main, then log that alt and say yes, and the census and treasury count you once. Heads up: the beta forgets addon data at login, so right now the offer can't reach the alt." },
		{ id = "feat-help-status", topic = "features",
			q = { "What are the commands?", "How do I use this addon?", "Where's the help?" },
			text = "Help button left of the X, or /syl help for all commands. /syl status shows diagnostics.",
			long = "Click the help button left of the window's X: what each tab is for, privacy switches, links and Report a bug. /syl help lists every command, and /syl status shows what your addon knows." },
		{ id = "feat-search", topic = "features",
			q = { "Can I search the lists?", "How do I find a name on a tab?" },
			text = "Most tabs have a search box on top. It only filters what you see.",
			long = "The Census, Realm, Tabards, Treasury, Decrees and Chat tabs have a search box: guilds, Veterans, players or zones on the Census, members on the Realm, players on Tabards, donors and bank items on the Treasury, the log on Decrees, lines on Chat. It only filters what you see." },
		{ id = "feat-open-window", topic = "features",
			q = { "How do I open Sylvanistas?", "Where's the window?" },
			text = "Type /syl, or click the minimap button or the round button in your guild window.",
			long = "Type /syl, click the minimap button, or the round button in your guild window. Shift-click the minimap button for the Chat tab; right-click it to show or hide the map markers." },
		{ id = "feat-gamepad", topic = "features",
			q = { "Does it work with a controller?", "The game froze in gamepad mode" },
			text = "With the gamepad UI Sylvanistas uses its own windows. If the game blocks something, /reload, then report it from the help button.",
			long = "Yes. With Blizzard's gamepad UI, Sylvanistas asks in its own windows (answer with the cursor) and leaves the world map alone. If the game blocks something, /reload clears it; report it from the help button, not /syl bug." },
		{ id = "feat-languages", topic = "features",
			q = { "Is it in Portuguese or Spanish?", "How do I change the language?" },
			text = "It follows your game language: English and Portuguese in full, Spanish, French and German for the main screens. Page help is in English.",
			long = "It follows your game language. English and Portuguese are complete; Spanish, French and German cover the main screens. The pages' ? help and the Answers are in English for now. Only what's on your screen changes." },
		{ id = "feat-key-block", topic = "features",
			q = { "How do I seal the channel?", "How do I ignore someone in Sylvanistas?" },
			text = "Officers: /syl key <secret> (same as other guilds) seals the channel. /syl block <name> ignores a player.",
			long = "Officers: /syl key <secret> seals the Sylvanistas channel so outsiders can't join. Use the same secret as the other Sylvanistas guilds or your guild splits off. /syl block <name> ignores everything a player sends." },
		{ id = "feat-sylvanistas-link", topic = "features",
			q = { "How do I get my Discord role?", "What's /syl discord?" },
			text = "Sylvanistas Link (Discord roles) isn't open yet: it comes with a later update of the addon.",
			long = "Sylvanistas Link will prove your character to the Sylvanistas bot on Discord for your role, but it isn't open yet: it needs a later addon update. Until then /syl discord just says it's not open." },
		{ id = "feat-issue-reporter", topic = "features",
			q = { "How do I hide Blizzard's Issue Reporter box?", "What's that Issue Reporter window at login?" },
			text = "Click Hide on the box or /syl issuereporter hide. The beta forgets it at login, so redo it after a relog.",
			long = "Click Hide on the box, or type /syl issuereporter hide; /syl issuereporter show brings it back. The beta forgets addon settings at login, so you may have to hide it again after a relog. With the gamepad UI Sylvanistas leaves it alone." },
		{ id = "feat-bridge", topic = "features",
			q = { "What's SylvanistasBridge?", "Can other addons read Sylvanistas?" },
			text = "A read-only door for the moderators' companion addon. It sends and changes nothing.",
			long = "A read-only door for the moderators' companion addon: it can ask whether a name is a Dreadguard and read chat lines your addon already accepted. It sends and changes nothing in Sylvanistas." },
		{ id = "feat-workshop", topic = "features",
			q = { "What's the Workshop tab?", "Why did I get a roll call?" },
			text = "The author's tab for versions and bug reports. You answer roll calls only if you said yes; /syl rollcall off stops them.",
			long = "The author's own tab: roll calls for versions and errors, asking out-of-date players to update, and bug reports players send him. Only he has it. You answer roll calls only if you said yes; /syl rollcall off stops them." },
		{ id = "feat-page-help", topic = "features",
			q = { "What does the ? on a page do?", "Where's the explanation of this page?" },
			text = "The ? in each page's bottom box (by the gear on the Chat tab) explains that page and why its counts can differ.",
			long = "Each page has a ? in its bottom box (next to the gear on the Chat tab): it explains that page and, where it shows counts, why they can differ between players. The help button left of the X is the general help." },
		{ id = "feat-quick-answers", topic = "features",
			q = { "What's the Answers button?", "How do moderators answer questions so fast?" },
			text = "The author, Dreadguard and Ambassadors have an Answers button: a click puts a ready answer in the box to edit, nothing is sent by itself.",
			long = "The author, the Dreadguard and the Ambassadors get an Answers button at the end of the Chat tab's box and in Sylvanistas's whisper window: short ready answers by topic, searchable. A click puts one in the box to edit; nothing is sent until you do." },
		{ id = "help-install", topic = "install-update-bugs",
			q = { "How do I install Sylvanistas?", "Where do I get the addon?" },
			text = "Get Sylvanistas Guild in the CurseForge app or WowUp (pick the Forever install), then restart the game.",
			long = "Get Sylvanistas Guild in the CurseForge app or WowUp and pick your Forever (beta) game install, not Classic Era. Then restart the game. By hand: unzip it so you end up with Interface > AddOns > Sylvanistas > Sylvanistas.toc." },
		{ id = "help-update", topic = "install-update-bugs",
			q = { "How do I update?", "I updated but nothing changed" },
			text = "Update in the CurseForge app or WowUp, then close and reopen the game (a /reload isn't enough).",
			long = "Update Sylvanistas Guild in the CurseForge app or WowUp, then close and reopen the game: a /reload won't load a new version properly. /syl status shows your version on its first line." },
		{ id = "help-check-version", topic = "install-update-bugs",
			q = { "Which version do I have?", "Am I up to date?" },
			text = "Type /syl status: the first line is your version, and a later line says if a newer one is out.",
			long = "Type /syl status: the first line shows your version, and a later line shows the latest release your addon heard of and whether you're behind." },
		{ id = "help-old-version", topic = "install-update-bugs",
			q = { "Do I have to update?", "My version is old, does it matter?" },
			text = "Please update: old versions drop what new ones send, and your guild can look broken to others. CurseForge or WowUp, then restart.",
			long = "Please do. Older versions drop what newer ones send, so your census can look off and your guild can look broken to everyone else. Update in the CurseForge app or WowUp, then restart the game." },
		{ id = "help-out-of-date", topic = "install-update-bugs",
			q = { "The AddOns list says 'out of date'", "Sylvanistas is disabled as out of date" },
			text = "That's the game's patch check, not Sylvanistas. Tick Load out of date AddOns in the AddOns list.",
			long = "That's the game comparing against its own patch number, not Sylvanistas's version. Tick Load out of date AddOns in the AddOns list and it loads." },
		{ id = "help-author-update-popup", topic = "install-update-bugs",
			q = { "I got a window saying the author asks me to update", "Is the update popup legit?" },
			text = "If it says the author asks, it's real: only his character can send it, and only if you're behind. Update and restart. /syl rollcall off stops his.",
			long = "If it says the author of the addon asks you, it's real: only his character can send it, and only when your version is older than the one he released. Update in the CurseForge app or WowUp, then restart. /syl rollcall off stops his. One naming a player is that player's ask." },
		{ id = "help-report-bug", topic = "install-update-bugs",
			q = { "Where do I report a bug?", "How do I send the author an error?" },
			text = "Sylvanistas window, help button (left of the X), Report a bug. If the author's online there's a button to send it to him.",
			long = "Open the Sylvanistas window, click the help button left of the X, then Report a bug. Copy the text to GitHub or a CurseForge comment. If the author is online, that window also has a button that sends it straight to him in game." },
		{ id = "help-blocked", topic = "install-update-bugs",
			q = { "The game says it blocked Sylvanistas", "I got an 'action blocked' error" },
			text = "A /reload clears it. Then report it: Sylvanistas window, help button, Report a bug (not /syl bug with the gamepad).",
			long = "A /reload clears it. Then tell us what happened: Sylvanistas window, help button, Report a bug. With the gamepad UI, don't type /syl bug in chat; use the button, since a typed command can set the block off again." },
		{ id = "help-settings-reset", topic = "install-update-bugs",
			q = { "My settings reset every login", "Why do I keep getting asked the same questions?" },
			text = "The beta forgets addon data at login. /syl backup and /syl restore bring your settings back; privacy answers are asked again each session.",
			long = "The beta forgets addon data at login right now, so settings and your privacy answers reset each session. /syl backup saves your settings as text and /syl restore puts them back, but not your privacy answers: those get asked again." },
		{ id = "help-safe", topic = "install-update-bugs",
			q = { "Is it safe? What does it send?", "Does the addon send my data anywhere?" },
			text = "It only uses the game's addon messages, no outside server. Location, chats and the rest wait for your yes (/syl privacy).",
			long = "It talks only through the game's own addon messages, with no server of its own. Your guild's census, your addon's hello and its version (to a player's Check version) go out as is; your location, chats and the rest wait for your yes. /syl privacy shows every switch." },
		{ id = "help-na-eu", topic = "install-update-bugs",
			q = { "Can NA and EU be linked?", "Why can't I see the EU guilds?" },
			text = "No: NA and EU are separate game worlds, so each has its own census.",
			long = "No, they're separate game worlds, and the addon only talks inside the game. Each region has its own census." },
		{ id = "help-other-clients", topic = "install-update-bugs",
			q = { "Does it work on Classic Era or Anniversary?", "Which game versions does Sylvanistas support?" },
			text = "Built for WoW: Forever, also tested on Classic Era and Anniversary.",
			long = "It's built for WoW: Forever, and also tested on Classic Era and TBC Anniversary. Pick the right game install in the CurseForge app." },
		{ id = "rc-see-version", topic = "right-click-1.1.2",
			q = { "How do I see someone's Sylvanistas version?", "Is my guildmate on the latest version?" },
			text = "Right-click them: the Sylvanistas line shows their version. Not seen yet? Pick Check version and their addon answers in a few seconds.",
			long = "Right-click the player (their name in chat, the guild roster or their portrait): the Sylvanistas line shows their addon version and whether it's up to date. Guildmates show by themselves; for anyone else pick Check version and their addon answers in seconds." },
		{ id = "rc-other-guilds", topic = "right-click-1.1.2",
			q = { "Why can't I see the version of someone in another guild?", "It says not seen for a player from another guild" },
			text = "Your addon only hears your own guild by itself. Right-click them and pick Check version; only 1.1.2 and newer answer, so no answer can mean an older one.",
			long = "Your addon only hears your own guild's versions by itself. For anyone else, right-click them and pick Check version: their addon answers with its version. Only 1.1.2 and newer answer, so no answer can mean no Sylvanistas, an older one, a dungeon or raid, or no Sylvanistas guild." },
		{ id = "rc-ask-update", topic = "right-click-1.1.2",
			q = { "How do I ask someone to update?", "Can I tell a guildmate their addon is old?" },
			text = "Right-click them, Ask to update (it shows when they're behind). 1.1.2+ get a small notice; for older ones it opens a whisper you send.",
			long = "Right-click them and pick Ask to update (it only shows when they're behind). On 1.1.2 or newer their addon shows a small notice with where to update; older ones can't, so it opens a whisper with the ask for you to send. One ask per player a day, 5 an hour." },
		{ id = "rc-got-asked", topic = "right-click-1.1.2",
			q = { "A window says someone asks me to update Sylvanistas", "A player asked me to update, is that legit?" },
